knowledge_base = {'name': 'Nalanda LIC Library FAQ', 'description': 'Question-and-answer knowledge base extracted from 1. QUESTIONS.txt', 'total_entries': 96, 'entries': [{'id': 1, 'questions': ['Tell me about Nalanda LIC', 'About the Library and Information Centre', 'Library history', 'When was the library established', 'Library mission', 'What is Nalanda LIC', 'Library overview'], 'answer': 'Nalanda Library and Information Centre\nEstablished in 2007, it supports 1,800+ students, faculty and researchers with world-class resources.\n🎯Mission: Advance Knowledge through Research & Innovation | Guide Learning | Inspire Curiosity\n📐 Two AC floors | Open access | 365 days | 41735 books | 6,00,007+ e-books | 83 Journals (Print) | 22000+ e-journals | 99 e-databases | 1,025 theses | 83754 Academic Videos | 40 Corporate Reports (Print) | 15000 Corporate Reports (Digital) | 3700 CD-ROM Publications | 3408 E-Case Collection | 6119 Bound Volumes | 220 Annual Reports'}, {'id': 2, 'questions': ['Where is the library?', 'How do I reach the library?', 'Library address', 'Which building is the library?', 'Library location on campus'], 'answer': '📍Library Location\nLibrary Building, in front of the Computer Centre and Auditorium — enter from the Ground floor.\n📮 P.O. IIM Kozhikode, Kunnamangalam – 673570, Keralam\n📞 0495-2809 143| 📧 library@iimk.ac.in'}, {'id': 3, 'questions': ['What are the library hours?', 'Is library open on Sundays?', 'When does library close?', 'Library working hours', 'Is it open today?', 'Library open on holidays?', 'What time does library open?', 'What are library timings?', 'Is there 24/7 reading hall?', 'Library timings'], 'answer': '🕘Library Timings\n📅Business Hours 8:00 am to 9:30 pm (Working Days)\n🏖Statutory Holidays: 9:00 AM – 5:30 PM\n ✅ Open 7 days, 362 days a year!'}, {'id': 4, 'questions': ['How to register for library membership?', 'How to get library card?', 'Who can join the library?', 'New member registration', 'Library membership process', 'How do I get library access?'], 'answer': '🎓Library Membership\nOpen to all IIMK students, faculty, staff & research scholars.'}, {'id': 5, 'questions': ['I am new to the library', 'First time visitor guide', 'How to start using the library', 'New student library guide', 'Getting started in library'], 'answer': 'Welcome to Nalanda LIC\nRegister at Circulation Desk, Ground floor — bring your IIMK ID\nSearch books via OPAC or the Books tab above\nAccess e-journals on campus WiFi — no login needed\nBorrow books via RFID kiosk or Circulation Desk\nGet help at the Reference Desk anytime\nNew Member Guide User Guides (Hyperlink required)'}, {'id': 6, 'questions': ['How do I borrow a book?', 'How to issue a book?', 'Book checkout process', 'How to use RFID kiosk?', 'Self checkout library', 'Do I need my ID to borrow?', 'Can I borrow books on holidays?'], 'answer': '📖 How to Borrow Books\n🖥 RFID Self-Checkout Kiosk (1st floor):\nTap "Issue/Borrow" on the screen\nPlace your IIMK ID card on the reader\nPlace books on the scan bed\nTap "Borrow" then "Exit" — done!\n\nCirculation Desk: Show IIMK ID to staff — they will issue the books.\n🔎 Search OPAC First'}, {'id': 7, 'questions': ['How to return a book?', 'Book drop box location', 'Can I return after hours?', 'Where is the book dropper?', 'Return books overnight', 'Where do I return books?'], 'answer': '↩️Returning Books\n\nCirculation Desk: Hand to staff during open hours.\n🖥 RFID Self-Check-in Kiosk (1st floor):\nTap "Return" on the screen\nPlace books on the scan bed\nTap "Return" then "Exit" — done! — return anytime!'}, {'id': 8, 'questions': ['How to renew a book?', 'Can I renew online?', 'How many times can I renew?', 'Book renewal online', 'Extend due date', 'How to extend my book issue period?'], 'answer': '🔄Book Renewal\n\n✅ Renew up to 3 times per book for faculty, and up to 2 times per book for others\n🌐Online (OPAC): Login → My Account → Loans → Renew\nDesk: Bring your IIMK ID\n📞Phone: 0495-2809 143\n⚠️ Cannot renew if reserved by another user.\n🔑 Login to Renew'}, {'id': 9, 'questions': ['How many books can I borrow?', 'Loan limit for PhD students', 'How long can I keep a book?', 'Borrowing quota per category', 'Faculty borrowing limit', 'Is borrowing limit different for PhD and PG Studnets?'], 'answer': '📋Borrowing Privileges\n\nFaculty —50 books / 90 days\nStaff Members —25 books / 60 days\nPhD Students / MSc —25 books / 60 days\nPG students —15 books / 30 days\nFamily Card —10 books/ 14 days\n🔄 Renew up to 3 times per book for faculty, and up to 2 times per book for others | 💸 Fine:  ₹2/book/day\n📜 Full Rules (Hyperlink of Rules and Regulations)'}, {'id': 10, 'questions': ['How much is the library fine?', 'How to pay the overdue fine?', 'I lost a library book', 'How to check my dues?', 'Late return penalty', 'Can I pay fine online?', 'What if I lost a book?', 'How much do I pay if a book is lost or damaged?'], 'answer': 'Fine & Due Policy\n\n💸Late return ₹2 per book per day\n🔴Lost book Market price + due charge\n🟡Damaged assessed by librarian\n💳Pay via UPI through Intranet\n💳 Check My Dues (OPAC Hyperlink)'}, {'id': 11, 'questions': ['How to reserve a book?', 'Can I place a hold on a book?', 'Book reservation process', 'How to put a book on hold?', 'Reserve checked out book', 'What to do if all copies are issued?'], 'answer': '📌Reserving a Book:\nIf a book is checked out, place a hold:\n🌐OPAC: Search → "Place Hold" (login required)\nDesk: Ask circulation staff\n✉️ You\'ll be notified by email when ready.\nPickup window: 2 working days after notification.\n🔎 Search & Reserve (OPAC Hyperlink)'}, {'id': 12, 'questions': ['How to get no dues from library?', 'Library no dues clearance', 'No objection certificate from library', 'Library clearance for graduation', 'Is no dues required for graduation?'], 'answer': '✅ No Dues / Clearance Procedure\n\n1️⃣   Return all issued books\n2️⃣   Clear all fines & collect receipt (if any)\n3️⃣   Visit Intranet to apply for no dues\n⚠️ Allow 1–2 working days — do this before your last day!\n📋 Full Clearance Guide (No dues rules hyperlink)'}, {'id': 13, 'questions': ['How to recommend a book for library?', 'Book purchase recommendation', 'Suggest a book to library', 'Request library to buy a book', 'Can I suggest a book to library?'], 'answer': '📝Recommend a Book for Purchase:\n\nNalanda LIC welcomes book recommendations from all members!\n📧 Email:libIIMK@IIMK.ac.in\nInclude: title, author, ISBN & reason for recommendation\n📋 Recommendation Guide📄 Forms (Hyperlink)'}, {'id': 14, 'questions': ['How to search the library catalogue?', 'How to use OPAC?', 'Find a book in the library', 'How to check book availability?', 'Library online catalogue', 'What is OPAC?', 'Where to find if the book is in the library or not?'], 'answer': '🔎OPAC — Online Library Catalogue: (Hyperlink of OPAC)\n\nSearch 41735+ books by Title, Author, Subject, ISBN, or Keyword.\nBooks uses DDC (Dewey Decimal Classification).\n💡Tip: Use the Book Search tab above for instant in-widget results!\n\n🔎 Open OPAC 📖 OPAC Guide (OPAC guide link)'}, {'id': 15, 'questions': ['What is a call number?', 'How to find a book on the shelf?', 'Library classification system', 'UDC classification IIMK', 'Which floor is my book on?', 'How to find a book with Call No.?'], 'answer': '📂Finding Books on the Shelf:\nNalanda LIC uses DDC (Dewey Decimal Classification).\n📍 Find the Call Number from the OPAC result → match it to the shelf label on that floor.\n🏢 Books are shelved numerically by subject code on open-access stacks across on first floors.\n🏢 Floor Plans🔎 Search OPAC (link)'}, {'id': 16, 'questions': ['How to check my library account?', 'OPAC login', 'How to see my issued books?', 'Check due dates online', 'Library account login', 'How to reset password?', 'How to see borrowed books?'], 'answer': '👤My Library Account (OPAC):\n🔑 Login credentials emailed after membership registration.\n\nYou can:\n• View issued books & due dates\n• Renew books online (up to 3/2×)\n• Check & pay fines\n• Place holds on unavailable books\n🔑 Login to My Account (Link)'}, {'id': 17, 'questions': ['How to access e-journals?', 'Subscribed journal list', 'Download research papers', 'Access journals from library', 'Which journals does Nalanda LIC have?', 'How many subscribed e-journals are there in library?'], 'answer': '📰E-Journal Access\n22000+ E-Journals from many publishers (Elsevier, Springer, Wiley, Nature, ACS, APS & more).\n📋ONOS: 13,000+ journals from 32 publishers — free for all IIMK members via the Govt. of India initiative!\n🔒 Access on campus WiFi or via VPN from home.\n📚 E-Journals A–Z📋 ONOS Info (ONOS link)'}, {'id': 18, 'questions': ['What is ONOS?', 'How does ONOS work?', 'Which publishers are in ONOS?', 'How many journals in ONOS?', 'ONOS access at IIMK', 'Can I get APC support from ONOS?', 'Is ONOS free?', 'What is One Nation One Subscription?', 'What subjects does ONOS cover?'], 'answer': '📋ONOS — One Nation One Subscription\nA Government of India initiative by PSA & INFLIBNET providing free access to 13,000+ journals from 32 top global publishers across 27+ disciplines.\n✅ IIM Kozhikode is a registered member — all members get free access!\n\nKey Publishers include: ACS, ACM, AIP, APS, AAAS, Annual Reviews, BMJ, CUP, Elsevier, IEEE, IOP, OUP, RSC, Sage, Springer Nature*, Wiley*, World Scientific & more.\n\n💰APC Support: Article Processing Charges for top-1% Open Access journals (by CiteScore/SNIP/SJR) are centrally funded via ONOS.\n📋 Full ONOS Details💰 APC Eligible Titles (APC Link)'}, {'id': 19, 'questions': ['How to access e-books?', 'Online books available?', 'Electronic books IIM Kozhikode', 'Semester e-books list', 'How many e-books are there in the library?', 'Where to find e-books?'], 'answer': '📱E-Books:\n📘6,00,007+ Subscribed E-Books: Springer, Elsevier, Wiley & more\n📗Semester E-Books: Course-specific titles each semester\n🔒 Access via campus network or VPN (My Loft)\n📘 Subscribed📗 Semester E-Books'}, {'id': 20, 'questions': ['Which databases does the library subscribe to?', 'How to use research databases?', 'Database access Nalanda LIC', 'Which management databases are available?', 'Which statistics databases are subscribed?', 'ACM digital library access', 'IEEE Xplore access', 'Does library have Scopus?', 'Does IIM Kozhikode have Web of Science?'], 'answer': '🗄Research Databases at Nalanda LIC:\nNote: Nalanda LIC does NOT currently subscribe to Web of Science — however, Scopus is available, which is subscribed independently\n\n📘 Full Text Databases (64 total):\nFinance, Investment & Capital Markets\nACE Equity NXT, ACE MF NXT, Bloomberg, Capital IQ Pro, LSEG Databases / Refinitiv Workspace, CRISIL i360, ICRA Research, Prime Database Group, Private Circle, Orbis / BankFocus, Venture Intelligence Service\nEconomics & Economic Data\nCMIE – Economic Outlook, CMIE – States of India, EPWRF India Time Series, India Data Portal, Indiastat.com, ICSSR Data Service\nBusiness & Management\nCMIE – Prowess dx, CMIE – Prowess Web, CMIE – Industry Outlook, EMIS Intelligence – India Service, MarketLine Advantage, Orbis, STATISTA, NASSCOM Membership\nMarketing, Advertising & Consumer Research\nEuromonitor Passport, MICA Market Intelligence (MIMI), MICA Village Market Intelligence (MVMI), WARC, TV Ad Indx, STATISTA eCommerce Insights\nEntrepreneurship, Startups & Innovation\nTracxn, Disruptor Database, Venture Intelligence Service, YNOS, Private Circle\nPsychology & Behavioural Sciences\nEBSCO APA PsycTests\nLaw & Legal Studies\nHeinOnline, LexisNexis / Nexis Uni, Westlaw Academic Package\nEngineering, Technology & Computer Science\nIEEE ASPP + POPALL\nSocial Sciences & Humanities\nICSSR Data Service, South Asia Archive, India Data Portal, Indiastat.com\nLibrary & Multidisciplinary Research\nEBSCO Discovery Service (EDS), Scopus, ProQuest Dissertations & Theses Global\nAcademic / Research Writing & Productivity Tools\nGrammarly, QuillBot Premium\nIndustry / Sector-specific Research\nCMIE – CapEx, CMIE – Consumer Pyramids DX, CMIE – Industry Outlook, CRISIL i360, NASSCOM\n🔒 Access on campus WiFi or via VPN (My Loft)\n🗄 Full Database List (Full link)'}, {'id': 21, 'questions': ['How to access library from home?', 'Myloft setup for library', 'Off-campus access to e-resources', 'Access journals from outside campus', 'Can I access library resources from home?', 'How can I use Grammarly outside the campus?', 'How to login to Myloft?', 'IIMK Myloft access', 'Remote access to e-resources'], 'answer': '🏠Off-Campus Access — Myloft Services\nBrowser-based My Loft from Nalanda LIC webpage — no software installation needed!\n📋Steps\n1️⃣   Go to: (IP address required)\n2️⃣   Login with IIMK username & password\n3️⃣   Access all databases & e-journals!\n⚠️ Do not share Myloft credentials\n🔒 Myloft Portal📋 Myloft Guide (Guide Link)'}, {'id': 22, 'questions': ['How to set up Myloft for library?', 'Myloft login steps IIMK', 'How to use Nalanda LIC/ IIMK Myloft?', 'Myloft how to login?', 'Steps to access e-resources from home', 'Myloft not working in the library', 'How do I connect to Myloft?', 'Myloft guide for library access'], 'answer': '🔐IIMK Web VPN — Step-by-Step:\n✅No software installation needed — it runs in your browser!\n\n📋Steps:\n1️⃣   Open: https://app.myloft.xyz/user/login?institute=cmjilnvlr045cwe01jz1yqii3\n2️⃣   Enter your IIMK username & password\n3️⃣   Click Login → you are now connected\n4️⃣   Access any subscribed database or journal\n\n📖 For detailed screenshots & tips, read the official PDF guide.\n⚠️ If login fails: check caps lock, or contact library.\n🔒 Myloft Login 📖 PDF Guide📋  VPN Page (Guide LINK)'}, {'id': 23, 'questions': ['How to access e-resources from home?', 'Off-campus access to journals', 'Access library from hostel', 'Access ScienceDirect from home', 'How to read papers from outside campus?', 'Download paper from home IIMK', 'Library access without being on campus'], 'answer': '🌐Accessing E-Resources Off-Campus:\n\n🔐IIMK Web VPN (Recommended):\n→ Login at: https://app.myloft.xyz/user/login?institute=cmjilnvlr045cwe01jz1yqii3 with IIMK credentials\n→ Full access to all 67 databases & 22000+ journals\n→ No software installs — browser-based!\n\n🆓 Free Open-Access (No VPN needed):\n• arXiv.org — physics, math, CS, bio preprints\n• PubMed Central — biomedical free full-text\n• NDL India — 90M+ resources\n• DOAJ — open access journals\n\n🔒 VPN Portal📋 VPN Guide (Guide LINK)'}, {'id': 24, 'questions': ['Cannot access journal article', 'E-resource not opening', 'Database login error', 'Access denied for paper', 'Why is journal blocked?', 'Cannot download paper', 'E-journal access problem', 'Database not loading', 'Full text not available'], 'answer': "🆘 E-Resource Access Troubleshooting:\n🔍Try these steps:\n1️⃣   On campus? Ensure you're on IIMK WiFi (not mobile data)\n2️⃣   Off campus? Connect via Myloft Web VPN first → (IP Address needed to add)\n3️⃣   Clear browser cache & try incognito mode\n4️⃣   Try a different browser (Chrome / Firefox)\n5️⃣   Verify the journal is in our subscribed list\n\n📧 Report issues: library@iimk.ac.in\nInclude: article URL, error message, browser used.\n📞 0495-2809 143/144\n🔒 Web VPN✅ Check Databases (Guide LINK)"}, {'id': 25, 'questions': ['Can I access library on my phone?', 'Mobile access to library resources', 'Access OPAC on mobile', 'E-journals on phone', 'Can I read papers on my phone?', 'Library on smartphone'], 'answer': '📱Accessing Library on Mobile:\n✅All library resources work in mobile browsers!\n\n📲On campus (IIMK WiFi):\n• Search OPAC: libraryopac.iimk.ac.in\n• Read & download e-journals & PDFs directly\n📲Off campus (mobile data/home WiFi):\n• Open Myloft in browser from Nalanda LIC website: (IP Address required here)\n• Login → access all resources as normal\n• Or use free resources: arXiv, PubMed — no VPN needed\n\n🔒 Web VPN📱 OPAC (Guide LINK)'}, {'id': 26, 'questions': ['How to download a research paper?', 'How to get full text of article?', 'Paper download IIMK', 'How to save journal article as PDF?', 'Get full text paper', 'Access full text article IIMK', 'Download paper from McKinsey Quarterly'], 'answer': '📥How to Download a Research Paper:\n\n📋On-campus (IIMK WiFi):\n1️⃣ Go to the journal website directly (McKinsey Quarterly, Springer, etc.)\n2️⃣ Click "PDF" or "Full Text" — downloads automatically\n\n📋Off-campus:\n1️⃣ Login to Web VPN: (OPAC IP Address)\n2️⃣ Then access the journal — full text available\n\n🆓Free (no VPN needed):\nall open access are freely available in the Nalanda LIC portal\n\n📧 Paper not accessible? Request via DDS/ILL: library@iimk.ac.in\n\n🔒 Web VPN📋 DDS'}, {'id': 27, 'questions': ['How to use Google Scholar?', 'Google Scholar IIMK access', 'Link Google Scholar to IIMK library', 'Full text via Google Scholar', 'Configure Google Scholar for IIMK users', 'Google Scholar library links', 'Setup IIMK in Google Scholar'], 'answer': '🔎Google Scholar + IIMK Library:\n\n💡Link Google Scholar to IIMK for 1-click full-text access:\n\n📋Setup (one-time, 30 seconds):\n1️⃣ Go to scholar.google.com\n2️⃣ Click ≡ Menu → Settings → Library Links\n3️⃣ Search "IIMK/ IIM Kozhikode" → enable → Save\n4️⃣ Papers now show "Full Text @ IIMK" links\n\n✅ On IIMK WiFi — works instantly.\n🔐 Off-campus — connect Web VPN/ Myloft first: (IP Address for Myloft)\n\n📋 VPN Guide📚 E-Journals A–Z (LINK required)'}, {'id': 28, 'questions': ['Are there computers in the library?', 'Library computer terminals', 'Internet access computer library', 'E-resource access on library PC', 'How many computers in library?', 'Can I use library computers?', 'Library desktop access'], 'answer': '🖥️Library Computer Terminals:\n\n✅Yes! IIMK Library has dedicated computers for e-resource access.\n\n💻Available:\n• OPAC terminals on all floors — for catalogue search\n• E-Resource workstations — for journals & database access\n• All 67 databases, 22,000+ journals accessible on campus PCs\n\n🔐 Login with IIMK credentials if prompted.\n⏰ Available during library hours: 8:00 AM – 09:30 PM\n\n🏢 Floor Plans🏛️ Library Spaces (LINK required)'}, {'id': 29, 'questions': ['Open access resources in library', 'National Digital Library access', 'Free online resources', 'Open educational resources IIMK', 'How to register for NDL?', 'What is NDL?'], 'answer': '🌐Open Access Resources:\n\n📖National Digital Library (NDL): Millions of free learning resources — register with IIMK email\n🌍 Open Access Journals\n📰 Open Access Newspapers\n🎓 Open Educational Resources (OER)\n🎬 E-Learning Portals: NPTEL, SWAYAM\n\n📚 NDL Info🎓 OER📋 NDL Registration Guide (Guide Link)'}, {'id': 30, 'questions': ['What e-learning portals does the library provide?', 'NPTEL access IIMK', 'SWAYAM courses', 'Online courses IIMK library', 'E-learning resources', 'Is NPTEL accessible through library?'], 'answer': '🎬E-Learning Portals:\n\nIIMK Library provides links to major e-learning platforms:\n\n🎓NPTEL — Video lectures by IIT/IISc faculty\n📚SWAYAM — Free online courses by GOI\n\n🎬 All E-Learning Portals🎓 NPTEL'}, {'id': 31, 'questions': ['Does the library have magazines?', 'E-magazines at IIMK library', 'Which magazines are available?', 'Online magazines access', 'Are there popular Management magazines?', 'What magazines are available for MBA?'], 'answer': '📰E-Magazines:\n\nIIMK Library subscribes to popular management and academic magazines in digital format.\n\n📖 Includes general interest and management-focused titles for leisure and research inspiration.\n\n📰 Browse E-Magazines (Link)'}, {'id': 32, 'questions': ['How to check plagiarism?', 'iThenticate access', 'Similarity check for thesis', 'UGC plagiarism guidelines', 'Plagiarism report IIMK', 'Is plagiarism check free?', 'Can students check plagiarism directly?'], 'answer': '🔍Plagiarism Detection (iThenticate):\n\n📊UGC Acceptable Similarity: Below 10%\n📧 Contact the computer centre for "iThenticate Request"'}, {'id': 33, 'questions': ['How to use Grammarly?', 'Grammarly access for students', 'Writing assistance IIMK library', 'Grammar check tool', 'Is Grammarly free for students?', 'How to access Grammarly through library?'], 'answer': '✍️Grammarly — Writing Assistance:\n\nIIMK Library provides Grammarly Premium access to all members for academic writing improvement.\n\n📧 Request access:library@iimk.ac.in\n✅ Use for: research papers, thesis, reports, assignments\n🏠 Also accessible off-campus once account is set up\n\n✍️ Grammarly Info (Grammarly Guide Link)'}, {'id': 34, 'questions': ['How to measure research impact?', 'h-index calculation', 'Improve citation count', 'ORCID registration', 'Research visibility IIMK', 'What is ORCID?', 'How to calculate H-Index?', 'How to calculate G-Index?'], 'answer': '📊Research Impact & Visibility:\n\n📈Measure impact: h-index & g-index via Scopus / Google Scholar\n🆔ORCID: Unique researcher ID linking all your publications\n👁Boost visibility: ResearchGate, Academia.edu, Google Scholar\n🗃IIMK OpenVault: Institutional open-access repository\n📊Scopus Insights: Graphical citation analysis available on library website\n\n📊 Impact Guide👁 Visibility Guide'}, {'id': 35, 'questions': ['How to cite a source?', 'APA citation format', 'IEEE citation style', 'Reference management tools', 'How to use Zotero?', 'Mendeley library', 'What is Zotero?', 'How many types of citation styles are there?'], 'answer': '📑Citation Styles & Reference Management:\n\nStyles: APA | IEEE | MLA | Chicago | Harvard | Vancouver\n\n🛠Free Tools:\n• Zotero — browser plugin + desktop\n• Mendeley — great for PDFs\n\n📑 Citation Styles Guide (https://gyanodaya.iimk.ac.in/storage/docs/usefulDocuments/CITATION%20GUIDELINES.pdf)'}, {'id': 36, 'questions': ['Document delivery service', 'How to get a paper not subscribed?', 'Interlibrary loan', 'Article request library', 'ILL request IIMK', 'What is document delivery service?', 'If an article is not available in library, where to get it?'], 'answer': "📨Document Delivery Service (DDS):\n\nCan't access a paper? We'll get it for you!\n\n📧 Email:library@iimk.ac.in with:\nArticle title, authors, doi/url, journal, year, volume, pages & your department\n\n⏰ Delivery within 2–5 working days | ✅ Free for all members"}, {'id': 37, 'questions': ['How to access IIMK theses?', 'IDR portal', 'PhD thesis repository', 'Submit my thesis to library', 'Download IIMK PhD thesis', 'How to access previous year theses?', 'Where can I find softcopy of dissertations?'], 'answer': '🎓Theses & Dissertations\n\n📱IIMK IDR: PhD theses online — free access!\n📚Print copies: ground Floor, Serials Section\n\n📤Submit Thesis\n1️⃣ Get thesis approved by supervisor & committee\n2️⃣ Plagiarism check — get iThenticate clearance from library\n3️⃣ Format as per IIMK guidelines (Title page, Declaration, Certificate, Abstract, Chapters, References, Appendices)\n4️⃣ Email soft copy (PDF) to library@iimk.ac.in after viva with:\n   • Thesis soft copy (PDF)\n   • Plagiarism report\n   • Supervisor approval email\n5️⃣ Library assigns DOI & uploads to IDR (publicly accessible)\n\n🌐 IDR Portal📧 Submit Thesis'}, {'id': 38, 'questions': ['IRINS IIMK', 'Research information system', 'IIMK publication database', 'Find IIMK faculty publications', 'IIMK OpenVault', 'Where to find faculty publication details?', 'How to find institutional research information?'], 'answer': '🗂IIMK Research & Publications:\n\n📊IRINS@IIMK: Researcher profiles & publications\n📈Scopus Insights: Graphical citation & h-index analysis on library website\n📚IIMK Publications: Books & research papers by IIMK authors\n🌟Featured Covers: Journal covers featuring IIMK research\n\n🗂 IRINS 📊 Scopus Insights'}, {'id': 39, 'questions': ['What study spaces are in the library?', 'Library facilities', 'Reading room details', 'Is there a group study room?', 'Library WiFi', 'Is there a silent study area?', 'Are charging points available?', 'What facilities does the library provide?'], 'answer': '🏛Library Spaces & Facilities\n\n🖥 Bloomberg & LSEG terminals with sufficient capacity for the users at first floor financial section\n🔇 Discussion rooms | Ideation Labs | 👥 Group Study Area | 🖥 Digital / E-Reading Section\n📚 Open Stacks (43,000+ books) | 📖 Reference Section\n🗞 Current Journals & Encyclopedias Section\n\n✅ Free WiFi | 🔌 Charging | ❄️ Full AC | ♿ Accessible\n🖥 Self-Checkout/ CheckIn RFID Kiosk\n\n✅ Book facilities before using it (Link)\n📚 Rules and regulations for facilities booking (Guide Link)\n🏛 Explore Spaces🏢 Floor Plans (Link)'}, {'id': 40, 'questions': ["Is there a children's library?", "Children's library timings", "What are the hours of children's library?", 'Kids books in library', 'Children library age limit', 'Can my child visit the library?', "Children's section IIMK library", "Who can use children's library?", 'Books for kids in library', "Children's library rules"], 'answer': "👧Children's Library — IIMK:\n\n⏰Opening Hours:\n• 24*7 hours\n• Book issue during business hours\n\n👦Age Limit: 5 to 15 years\n👨👧 Children below 10 must be accompanied by a parent/guardian.\n🪪 Dependents of IIMK employees — carry IIMK ID/Family Card.\n\n📚Borrowing: 2 books for 15 days | Fine: ₹5/day overdue\n📋 Books issued to the IIMK employee's account (email notification sent).\n\n🌟Special Collections:\n• Harry Potter · Roald Dahl · Ruskin Bond · Sudha Murthy\n• Nancy Drew · Om Kidz Encyclopedia · Eminent Persons of India\n\n\n❌Not allowed: Personal belongings or books inside · Food & beverages\n✅ Open access — children can browse shelves freely.\n\n👧 Children's Library Page🔍 Browse Collection (Link)"}, {'id': 41, 'questions': ['How to contact the library?', 'Library email address', 'Library phone number', 'Staff contact the library', 'Library helpdesk', 'What is the library contact number?', 'How can I contact library staff?', 'How to contact the librarian?'], 'answer': '📬Contact Central Library\n\n📧library@iimk.ac.in\n📞0674-2494171\n⏰ 8:00 AM – 9:30 PM (all business days)\n⏰ 9:00 AM - 5:30 PM (All days)\n🤝 Walk-in: Circulation Desk, Ground Floor\n\n🤝 Connect👥 Library Team❓ FAQs (FAQs Link)'}, {'id': 42, 'questions': ['What new books have arrived?', 'Recent book additions', 'Latest books in the library', 'New books this month', 'How can I check new arrivals?', 'Is there any way to see recently added books?'], 'answer': '🆕New Arrivals:\n\nIIMK Library regularly adds new books across all subjects.\n📋 View the latest additions on the library website.\n📢 New arrival notices are posted on notice boards & email newsletter.\n\n📚 View New Arrivals (LINK)'}, {'id': 43, 'questions': ['Subject guide for Travel and Tourism', 'Research guide for Start -ups', 'Library guide for Telecommunication', 'How to research a topic?', 'Subject resource guide', 'Where can I find relevant resources for my department?', 'Are subject guides available online?'], 'answer': '📖Subject Guides: (link https://nalandakyr.iimk.ac.in/subjects/index.php)\n\nCurated guides for all resources available in the Nalanda LIC for IIMK community.\nEach guide lists: key databases, e-journals, reference books & open access resources.\n\n📖 Browse Subject Guides (Link for subject guide)'}, {'id': 44, 'questions': ['AI tools for research', 'Recommended AI for researchers', 'Research AI assistance IIMK', 'ChatGPT for research', 'Are there free AI tools for students?', 'Can you suggest AI tools for my research?', 'Does the library provide AI writing assistance?', 'Suggest some useful AI research tools?'], 'answer': '🤖AI Research Assistance:\n\n🧠 Recommended: Gemini, ChatGPT, Copilot, Elicit, Consensus, Research Rabbit\n✍️ Writing: Grammarly, Quillbot Premium (institutional access via library)\n📚 Literature: Connected Papers, Semantic Scholar\n\n⚠️ Always verify AI outputs and cite original sources!\n\n🤖 AI Assistance Guide (link) to be prepared'}, {'id': 45, 'questions': ['Library forms download', 'Membership form download', 'Gate pass form library', 'Library forms list', 'Where can I download library forms?', 'Is the form available online?', 'What forms are available?'], 'answer': '📋Library Forms: (Link)\n\nAll forms available for download:\n📄 Membership | Gate Pass | Book Recommendation | No-Dues | ILL Request | Gift Book Submission\n\n📋 Download All Forms'}, {'id': 46, 'questions': ['Is there WiFi in library?', 'Library internet access', 'WiFi password library IIMK', 'Free WiFi library', 'Internet in library IIMK', 'Library network access'], 'answer': '📶Library WiFi\n\n✅Free WiFi available throughout all floors of the library!\n\n📶 Connect to IIMK campus WiFi for automatic access to all e-journals & databases — no extra login needed for most!\n\n🏠Off-campus? Use Web VPN: Myloft login (IP link)\n\n🔒 VPN Portal🏛️ Library Spaces (Myloft link)'}, {'id': 47, 'questions': ['Library accessibility services', 'Disabled student support', 'Visual impairment library help', 'Adaptive services library', 'Is the library accessible to wheelchair users?', 'Is there support for visually impaired students?', 'JAWS software library', 'Ramp lift library IIMK', 'PWD facilities library', 'Differently abled library support'], 'answer': '♿Adaptive Ability Services — IIMK Library:\n\n👁For Visually Challenged Users:\n• JAWS Software — screen reader that reads all on-screen content aloud, enabling independent computer use\n• Personal Assistance — trained staff available to help navigate library resources\n\n🦽For Persons with Diverse Abilities:\n• Materials Retrieval — request staff at the Circulation Desk to retrieve materials\n• OPAC assistance — staff can help with book searches, holds & renewals\n• Ramp & Lift — throughout the library for easy mobility access\n• PWD Toilet — fully accessible toilet facility\n• Accessible seating — available on all floors\n\n📞Contact for assistance:\n• Circulation Desk:library@iimk.ac.in | +91-0495-2809 (Extn: 143)\n\n♿ Adaptive Services Page (Link)'}, {'id': 48, 'questions': ['Any free trial databases available?', 'Trial access to journals IIMK', 'New database trial library', 'Which databases are currently on trial?', 'What do you mean by trial access?', 'Can I download articles during trial?', 'trial access', 'trial database', 'trial resource', 'trial period', 'free trial access'], 'answer': '🆓Trial Access:\n\nIIMK Library periodically arranges free trial access to new databases, journals & e-books for community evaluation.\n\n📋Recent trial (ended): Bloomberg — trial has now concluded.\n\n🔔No active trial at this time. Watch the library website for new announcements.\n📢 Trials are posted on the library website & notice boards\n⏰ Typically available for 2–4 weeks\n📧 Suggest a trial: library@iimk.ac.in\n\n🆕 Trial Access Page (Link)'}, {'id': 49, 'questions': ['What is Current Awareness Service?', 'How to get alerts for new journals?', 'Library newsletter IIMK', 'How to stay updated on new resources?', 'Does library send email alerts?', 'How do I get notified about new books?', 'What is CAS?', 'How to subscribe to library alerts?'], 'answer': '📢Current Awareness Service (CAS):\n\nStay updated with the latest library resources!\n\n📧IIMK Newscast: Regular library news & updates\n📋TOC (Table of Contents): New issue alerts for print journals\n📰New Arrivals: Book additions posted regularly\n\n📧 Contact library@iimk.ac.in to subscribe\n\n📢 CAS Info📰 IIMK Newscast'}, {'id': 50, 'questions': ['Does library have print journals?', 'Bound journals in library', 'Table of contents for journals', 'Where to find printed journals?', 'Current issues of journals', 'How many bound journals are there?', 'Where is the print journal section?'], 'answer': '🗞Print & Bound Journals:\n\n📚6119 bound Journals — historical print volumes on library shelves\n📋Current Journal Issues: Displayed in the Current Journals & Periodical Section on the ground floor\n📑TOC Service: Table of Contents alerts for new print journal issues\n\n📑 TOC Alerts🏢 Journal Location (link)'}, {'id': 51, 'questions': ['Who are the library staff?', 'Library committee IIMK', 'Who is the librarian?', 'Library management team', 'Library staff contact', 'Who is in charge of the library?', 'Institute library committee members?'], 'answer': '👥Library Team & Committee:\n\nIIMK Library is managed by a dedicated professional team and overseen by the Institute Library Committee.\n\n📋 For specific staff contacts and committee members, visit the links below.\n\n👥 Library Team (https://library.iimk.ac.in/team-lic) 🏛 Library Committee (https://library.iimk.ac.in/general/5)'}, {'id': 52, 'questions': ['What is the e-resources usage policy?', 'Rules for using e-resources', 'Can I download bulk articles?', 'Is bulk downloading allowed?', 'Rules for database access', 'Fair use policy library', 'Systematic downloading policy'], 'answer': '📜E-Resources Usage Policy: (Link)\n\n⚠️Important Rules:\n• Personal & academic use only — no bulk/systematic downloading\n• Do NOT use bots, crawlers or scripts to download content\n• Violation may result in IP block for entire institution\n• Each article must be downloaded individually\n• Do not share login credentials\n\n📜 Full Usage Policy (Link for usage policy)'}, {'id': 53, 'questions': ['QR codes library IIMK', 'Quick access to library resources', 'Library QR code', 'Scan to access the library', 'QR code for OPAC'], 'answer': '📱QR Codes for Quick Access:\n\nIIMK Library provides QR codes for instant mobile access to key resources: OPAC, E-Journals, Databases, Forms & more.\n\n📌 QR code posters are displayed throughout the library. (QR Codes link)\n\n📱 View QR Codes'}, {'id': 54, 'questions': ['Can external visitors use the library?', 'Guest access to the library', 'Visitor policy IIMK library', 'Can alumni use the library?', 'Outsider access to the library', 'I am not an IIMK student. Can I use the library?'], 'answer': '🏛Visitor Access:\n\nIIMK Library has a Visitor Corner for external guests & collaborators. (External membership link)\n\n👤 Visitors must register at the Main Gate & obtain a visitor pass\n📋 Academic visitors may get limited access — contact the library in advance\n\n📧 library@iimk.ac.in for visitor arrangements\n\n🏛 Visitor Corner Info (rules link for visitors)'}, {'id': 55, 'questions': ['How to publish open access?', 'APC charges for publishing', 'Open access journals publishing', 'How to publish in OA journals?', 'What is APC?', 'ONOS APC support for publishing', 'How to apply for APC funding?'], 'answer': '🌍Open Access Publishing:\n\n📤How to Publish Open Access:\n• Gold OA: Publish in fully OA journals (may require APC)\n• Green OA: Self-archive in arXiv\n\n💰APC Support via ONOS: Top-1% OA journals (by CiteScore/SNIP/SJR from Scopus) qualify for centrally-funded APCs.\n\n🌍 OA Publishing Guide💰 Apply for APC (https://www.onos.gov.in/apc-support)'}, {'id': 56, 'questions': ['Online newspapers at the library', 'Which newspapers can I read?', 'Free newspaper access IIMK', 'Digital newspapers library', 'E-newspapers available', 'Which online newspapers are available in the library?'], 'answer': '📰Open Access Newspapers:\n\nIIMK Library provides access to a curated list of open-access newspapers and news portals.\n\n📖 Browse current affairs, science news & more at no charge.\n\n📰 Browse Newspapers'}, {'id': 57, 'questions': ['Can I bring my laptop to the library?', 'Is laptop allowed in library?', 'Can I use my laptop in library?', 'Laptop policy library', 'Can I work on my laptop in library?', 'Are personal laptops permitted?'], 'answer': '💻Laptops in the Library:\n\n✅Yes, personal laptops are allowed!\n\n🔌 Power sockets available at reading tables on all floors\n💡 Use in designated quiet zones — mute sound or use earphones\n📶 Connect to IIMK WiFi for internet access\n\n⚠️ Keep your laptop secure — the library is not responsible for loss/theft.\n🔒 Laptop lockers available near the entrance (limited).\n\n🏢 Floor Plans (link)'}, {'id': 58, 'questions': ['Can I bring a water bottle to the library?', 'Is water allowed in library?', 'Can I drink water in the library?', 'Water bottle policy', 'Can I carry drinks to library?', 'Are beverages allowed in library?'], 'answer': '💧Water Bottle Policy:\n\n✅Plain water in a sealed/closed bottle is allowed.\n\n❌Not allowed: Open cups, hot drinks (tea/coffee), soft drinks, juices or any food items inside the reading areas.\n\n🍽️ For snacks and meals, please use the cafeteria/canteen at NISARG Open Library complex outside the main library.\n\n📋 This helps protect books and equipment from spills.'}, {'id': 59, 'questions': ['Can I eat in the library?', 'Is food allowed in library?', 'Can I bring snacks to library?', 'Food policy library', 'Can I eat lunch in library?', 'Are eatables allowed?'], 'answer': '🍱Food Policy:\n\n❌Food and eatables are NOT allowed inside the library reading areas.\n\nThis includes: biscuits, chips, tiffin, packed meals, etc.\n☕ Hot drinks (tea/coffee) are also not permitted inside.\n\n✅Water in sealed bottles is the only exception.\n\n🍽️Cafeteria is available on campus/ open library complex — please eat there and return!'}, {'id': 60, 'questions': ['Is the library silent?', 'Can I talk in the library?', 'Phone rules in library', 'Noise policy library', 'Can I take calls in library?', 'Group discussion allowed in library?', 'Are group study rooms available?'], 'answer': '🔇Silence & Conduct Policy:\n\n📵Mobile phones: Keep on silent/vibrate. No calls inside — step outside to talk.\n🤫Reading areas: Maintain silence — no group discussions.\n💬Group study: Use the Group Discussion Room (check availability at the room facility portal of the library)(https://library.iimk.ac.in/general/36)\n🎧 Earphones/headphones allowed for laptop use.\n\n🤝 Please be considerate of other readers at all times.\n\n📜 Library Rules (Link for rules)'}, {'id': 61, 'questions': ['Can I bring my bag inside library?', 'Bag policy library', 'Where should I keep my bag?', 'Locker facility library', 'Is there a cloakroom?', 'Can I bring backpack to library?', 'Where to deposit bag?'], 'answer': '🔒Bag & Locker Policy:\n\n🎒Large bags & backpacks must be deposited at the Bag Deposit Counter near the library entrance.\n\n✅Allowed inside: Laptop bags (transparent or checked), small pouches, notebooks, stationery.\n🔒Lockers available near the entrance — bring your own lock or ask at the desk.\n\n⚠️ The library is not responsible for items left in bags or lockers.\n📋 Collect your bag token at the deposit counter.'}, {'id': 62, 'questions': ['Do I need ID card for library?', 'Which ID to carry to library?', 'Can I enter library without ID?', 'Is student ID mandatory for library?', 'ID proof for library access'], 'answer': '🪪ID Card for Library Access:\n\n✅IIMK Institute ID card is required for entry and for borrowing books.\n\n📋 Show your ID at the entrance gate/security.\n📚 ID is mandatory at the Circulation Desk for:\n  • Borrowing books\n  • Renewing books\n  • Getting No Dues clearance\n\n😕 Lost your ID? Contact the digital library Section for a duplicate.'}, {'id': 63, 'questions': ['I lost something in library', 'Lost and found library', 'I forgot my book in library', 'Lost my belongings in library', 'Found something in library', 'Lost item library'], 'answer': '🔍Lost & Found:\n\n📍 Report lost items or hand in found items at the Circulation Desk, Ground floor, situated at the entrance.\n\n📞 Call: 0495-2809 extn: 143\n📧 Email: library@iimk.ac.in\n\n⚠️ The library is not responsible for personal belongings left unattended.\n💡 Tip: Always keep your valuables (phone, wallet, laptop, tablet) with you or deposit bags at the bag counter.'}, {'id': 64, 'questions': ['Library orientation for new students', 'Library tour IIMK', 'Induction programme library', 'How to get library training?', 'Library walkthrough for freshers', 'Orientation session library'], 'answer': '🎓Library Orientation / Tour:\n\nIIMK Library conducts orientation sessions for new students & faculty at the start of each semester/year.\n\n📅When: Beginning of academic year (usually July–August)\n👨🏫Covers: Floor tour, OPAC demo, e-resources access, borrowing, WiFi, rules\n\n📧 You can also request a personal library tour by emailing librar@iimk.ac.in\n\n🆕 New to Library Guide (Link for guide)'}, {'id': 65, 'questions': ['Is there a dress code for library?', 'What to wear in library?', 'Dress code IIMK library', 'Can I enter library in shorts?', 'Any dress restrictions library?'], 'answer': "👔Dress Code:\n\n✅No strict dress code — casual and comfortable attire is acceptable.\n\n👟 Wear decent, appropriate clothing suitable for an academic environment.\n🚫 Avoid shorts, sleepwear, sports gear or clothing with offensive text/graphics.\n\nIIMK Library is a shared academic space — please dress appropriately and maintain the decorum of India's Premium Management institution."}, {'id': 66, 'questions': ['What are the library rules?', 'Library regulations IIMK', 'Code of Conduct Library', 'Rules and regulations library', "Dos and don'ts in the library", 'Library discipline policy'], 'answer': '📜Library Rules & Regulations:\n\n✅Allowed:\n• Personal laptops & tablets\n• Sealed water bottles\n• Notebooks & stationery\n• Earphones for laptop use\n\n❌Not Allowed:\n• Food, eatables, hot drinks\n• Mobile calls inside (step outside)\n• Loud conversations in reading areas\n• Bulk downloading of e-resources\n• Large bags (deposit at counter)\n\n🚫 Violation may lead to suspension of library privileges.\n\n📜 Full Rules (link for general rules)'}, {'id': 67, 'questions': ['What happens if I break library rules?', 'Library account suspended', 'Banned from the library', 'Library penalty for misconduct', 'What if I violate library policy?', 'Consequences of breaking library rules'], 'answer': '🚫Library Penalty & Suspension:\n\nRepeated violations or serious misconduct may result in:\n\n⚠️ Formal warning\n📵 Temporary suspension of borrowing privileges\n🔒 Account block until dues are cleared\n🚫 Permanent bar in extreme cases\n\nCommon reasons: overdue books, unpaid fines, bulk downloading, and misconduct.\n\n📧 Appeal or query: library@iimk.ac.in\n📞  0495-2809 extn: 143\n\n📜 Library Rules (link)'}, {'id': 68, 'questions': ['Forgot OPAC password', 'How to reset OPAC password', 'Cannot login to OPAC', 'OPAC login not working', 'OPAC username and password', 'How do I get my OPAC credentials?'], 'answer': '🔑OPAC Login Help:\n\n🆔Username: Your IIMK email ID (without @iimk.ac.in)\n🔐Password: Sent to your IIMK email after registration\n\n🔁Forgot Password?\n→ Click "Forgot your password?" on the OPAC login page\n→ Enter your email — reset link will be sent\n\nStill stuck? Contact:\n📧 library@iimk.ac.in | 📞 0495-2809 extn: 143\n\n🔑 OPAC Login: http://libraryopac.iimk.ac.in/'}, {'id': 69, 'questions': ['Can I borrow books from other libraries?', 'Inter library loan IIMK', 'Book not available in IIMK library', 'How to get book from another library?', 'ILL service', 'Library loan from other institute'], 'answer': '🔄Inter-Library Loan (ILL):\n\nIf a book is not available in IIMK Library, you may request it through:\n\n📚INFLIBNET N-LIST / DELNET — national library network\n📋 Submit a request at the Circulation Desk or email the library\n⏳ Delivery time: 3–7 working days, depending on the source\n\n📧 library@iimk.ac.in with subject: "ILL Request – [Book Title]"\n📞 0495-2809 extn: 143\n\n📋 Document Delivery (link)'}, {'id': 70, 'questions': ['How are books arranged in a library?', 'Library classification system IIMK', 'What is DDC?', 'How to find books by call number?', 'Library shelf arrangement', 'How does the library organise books?'], 'answer': '📂Library Classification System:\n\nIIMK Library uses DDC (Dewey Decimal Classification) — a scientific classification system ideal for broad library classifications.\n\n📖How to locate a book:\n1️⃣ Search OPAC → note the Call Number\n2️⃣ Call number = Subject code + Cutter number (author code, i.e. first three letter of author surname)\n3️⃣ Books are shelved numerically by call number on each floor\n\n💡 Example:658.421 DEO → Management section, Deodhar, Shrish\n\n🔎 Search OPAC🏢 Floor Plans (http://libraryopac.iimk.ac.in/cgi-bin/koha/opac-main.pl)'}, {'id': 71, 'questions': ['How to access Scopus?', 'Scopus database IIMK', 'Scopus citation search', 'Find citations on Scopus', 'Is Scopus available at IIMK?', 'Scopus login IIMK'], 'answer': "📊Scopus — Elsevier's Citation Database:\n\n✅Subscribed independently — IIMK Library have a direct Scopus subscription.\n\n✅What more is available:\n• IRINS@iimk — publication & citation data for IIMK researchers\n• Google Scholar — free citation search\n\n📧 For further help:library@iimk.ac.in\n\n📊 Scopus Insights🗂 IRINS🗄 All Databases"}, {'id': 72, 'questions': ['How to access Web of Science?', 'Web of Science IIMK', 'WoS database', 'Is Web of Science available?', 'Journal impact factor check', 'WoS login'], 'answer': '🌐Web of Science (WoS):\n\n❌NOT subscribed — IIMK Library does not have an independent subscription to Web of Science.\n\n✅Alternatives available at IIMK:\n• IRINS@iimk — researcher profiles & publication data\n• Google Scholar — free citation tracking\n• Databases subscribed for by IIMK Library (https://library.iimk.ac.in/a-zResource)\n\n📧 Need WoS access? Contact:library@iimk.ac.in\n\n🗂 IRINS📊 Scopus🗄 All Databases (all link)'}, {'id': 73, 'questions': ['How to access Sage E-Journals?', 'Sage E-Journals IIMK', 'McKinsey Quarterly access', 'Taylor & Francis E-Journals/ books online', 'Is Springer available at IIMK?'], 'answer': '📗SpringerLink / Springer Nature:\n\n✅Available at IIMK via ONOS subscription + campus WiFi.\n\n📚 Access:\n• Thousands of Springer/ Sage/ McKinsey Quarterly journals & e-books\n• Lecture Notes in Finance, Accounting & Control, Marketing Management, Strategic Management & more\n\n🔗 Just visit on campus — IP-authenticated, no login needed.\n📱 Off-campus: IIMK Myloft login required.\n\n📗 Open all e-resources (https://library.iimk.ac.in/a-zResource)'}, {'id': 74, 'questions': ['How to access ScienceDirect?', 'Elsevier journals IIMK', 'ScienceDirect access', 'Is ScienceDirect available?', 'Elsevier e-journals', 'ScienceDirect login IIMK'], 'answer': '📘ScienceDirect (Elsevier):\n\n✅Available at IIMK via ONOS + campus WiFi.\n\n📰 Access thousands of Elsevier journals including:\n• Cell, Lancet, Letters, JACS and more\n• Full-text articles in PDF & HTML\n\n🔗 Visit ScienceDirect on campus — IP-authenticated.\n📱 Off-campus: Use IIMK Myloft login.\n\n📘 Open ScienceDirect (http://www.sciencedirect.com/)'}, {'id': 75, 'questions': ['How to access IEEE ASPP?', 'IEEE database IIMK', 'IEEE journals and conference papers', 'Is IEEE available at IIMK?', 'Access IEEE papers'], 'answer': '⚡IEEE ASPP:\n\n✅Available at IIMK via campus WiFi (subscription access).\n\n📰 Access:\n• IEEE Transactions, Journals & Conference Proceedings\n• IET publications\n• Standards documents\n\n🔗 Visit IEEE ASPP on campus — IP-authenticated.\n📱 Off-campus: IIMK Myloft login required.\n\n⚡ Open IEEE ASPP (All Society periodical package) + POPALL (IEEE Proceedings Order Plan) (http://www.ieee.org/ieeexplore)'}, {'id': 76, 'questions': ['How to access CMIE - PROWESS dx?', 'CMIE - PROWESS dx IIMK access', 'CMIE - PROWESS dx', 'CMIE - PROWESS dx database', 'Is CMIE - PROWESS dx available at IIMK?'], 'answer': '🔬CMIE - PROWESS dx Portfolio Database:\n\n✅Several CMIE databases available at IIMK Library including CMIE - PROWESS dx via independent subscription at IIMK.\n\n📰 Includes: Finance, Accounting & Control, Economics, Marketing Management & more.\n\n🔗 Access directly through on-campus WiFi.\n📱 Off-campus: IIMK Myloft Login.\n\n🔬 CMIE🗄 Check Full List (https://library.iimk.ac.in/a-zResource)'}, {'id': 77, 'questions': ['How to access Bloomberg?', 'Free Finance, Accounting & Control papers online', 'Bloomberg/ LSEG', 'How to access LSEG?'], 'answer': '📄Bloomberg/ LSEG terminal:\n✅The Bloomberg Professional Service is a research tool for financial professionals as well as business academics who require in-depth and timely access to current business and company news, and financial and economic data\n✅LSEG provides a suite of powerful financial databases and research tools accessible via LSEG Workspace\n\n✅Subscribed!\n\n📚Bloomberg Covers: Company Financial Data; Banking & Financial Services; Annual Reports; Credit Ratings; CSR/ ESG.\n📚LSEG Covers: Global financial markets, company data, banking and financial services, capital markets, corporate governance, CSR/ESG, economic indicators, Certification.\n\n✅At IIMK you can:\n• Use and explore both terminals on the first floor at library\n\n\n📄 Read more (https://library.iimk.ac.in/a-zResource)'}, {'id': 78, 'questions': ['How to access Capital IQ Pro?', 'Capital IQ Pro IIMK', 'Capital IQ Pro database access', 'Capital IQ Pro search', 'Capital IQ Pro', 'Is Capital IQ Pro available at IIMK?'], 'answer': '🧬Capital IQ Pro:\n\n📚Use Capital IQ Pro for:\nS&P Capital IQ Pro platform bringing together an unrivalled breadth and depth of data, news, and research, combined with tech-forward productivity tools\n\n🔗For receiving login credentials, please send an email to library@iimk.ac.in\n\n🔗Access Method: One Time Registration(using iimk email)\n\n📚Subject Area: Public company financials, estimates, ownership, and transaction data; Deep industry data; Private company and private markets data; Expert opinions and forecasts; ESG scores, news, analytics, and solutions; Supply chain intelligence; Timely breaking news; Credit risk indicators and research; Real-time market prices.\n\n🧬 Open Capital IQ Pro: https://www.capitaliq.spglobal.com/'}, {'id': 79, 'questions': ['What reference manager should I use?', 'Mendeley IIMK', 'Zotero reference software', 'How to manage references?', 'Bibliography manager', 'Citation software', 'Reference management tool', 'Does QuillBot Premium generate citations?'], 'answer': '🗂️Reference Management Tools:\n\nIIMK Library recommends these free tools:\n\n📌Mendeley (Elsevier) — sync with ScienceDirect, free 2GB\n📌Zotero — open source, browser plugin, great for all databases\n📌EndNote Basic — web-based, integrates with WoS\n\n✅ All work with Word, LaTeX & Google Docs.\n📥 Download free from their websites.\n\n📌 Mendeley📌 Zotero 📌QuillBot premium (link)'}, {'id': 80, 'questions': ['How to write thesis in LaTeX?', 'Overleaf IIMK', 'LaTeX template for thesis', 'LaTeX writing tool', 'Is Overleaf available?', 'IIMK thesis LaTeX template', 'Is Overleaf subscribed by IIMK library?'], 'answer': '📝LaTeX & Overleaf:\n\n⚠️Overleaf — NOT subscribed by IIMK Library.\n\n✅However, Overleaf has a free plan available to everyone — you can sign up individually at overleaf.com at no cost.\n\n📄IIMK Thesis LaTeX Template: Available at the library or IDR for reference — email library@iimk.ac.in\n🔬 LaTeX is widely used for: research papers, theses, presentations (Beamer), and scientific documents.\n\n📚Free Resources:\n• Overleaf Documentation & Tutorials\n• BibTeX / BibLaTeX for reference management\n• Ask library staff for IIMK-specific LaTeX templates\n\n📝 Sign Up Free on Overleaf🎓 IIMK IDR (Overleaf link)'}, {'id': 81, 'questions': ['What is ORCID?', 'How to create an ORCID?', 'ORCID for researchers', 'Researcher ID IIMK', 'How to link publications to ORCID?', 'ORCID profile'], 'answer': '🆔ORCID (Open Researcher and Contributor ID):\n\n🆓Free, persistent researcher identifier — register at orcid.org\n\n✅Why you need ORCID:\n• Uniquely identifies you across all publications\n• Required by many journals for submission\n• Links all your papers regardless of name variations\n• Integrates with Scopus, WoS, IRINS & more\n\n📋 IIMK encourages all researchers & students to register.\n\n🆔 Register ORCID (https://orcid.org/)'}, {'id': 82, 'questions': ['How to check journal impact factor?', 'Is this journal good?', 'Journal ranking IIMK', 'How to find the ABDC journal?', 'How to find SCI journals?', 'Q1 Q2 journal list', 'Best journal for publication', 'Predatory journal check'], 'answer': "📈Checking Journal Impact Factor & Quality:\n\n🔍Tools to check:\n• JCR (Journal Citation Reports) — Impact Factor via WoS\n• Scopus — CiteScore, SJR, SNIP\n• Scimago — free Q1/Q2/Q3/Q4 ranking\n• ABDC journal list (https://abdc.edu.au/abdc-journal-quality-list/)\n\n⚠️Avoid Predatory Journals:\n• CheckBeall's List\n• Verify ISSN on ISSN Portal\n• Check if indexed in WoS/Scopus\n\n📊 JCR📈 Scimago (link)"}, {'id': 83, 'questions': ['Where to store research data?', 'Research data management IIMK', 'How to share research data?', 'Data repository for research', 'Open data publishing', 'FAIR data principles'], 'answer': '💾Research Data Management:\n\n📦Where to store & share data:\n• Zenodo — free, CERN-hosted, DOI for datasets\n• Figshare — figures, datasets, posters\n• OSF (Open Science Framework) — full project hosting\n• IIMK IDR — institutional repository for theses\n\n📋FAIR Principles: Make data Findable, Accessible, Interoperable, Reusable.\n\n💾 Zenodo🎓 IIMK IDR'}, {'id': 84, 'questions': ['Where can I study quietly?', 'Best place to study in library', 'Study tables available?', 'Reading hall library', 'Quiet study area', 'Library seating capacity', 'Individual study cubicle'], 'answer': '📖Study Spaces in the Library:\n\n🏢2 Floors of study areas:\n• 1st Floor: Circulation, OPAC terminals, general reading, Quiet reading, periodicals, Deep study zone, group discussion room, Gurukul\n• 2nd Floor: Book stacks, reference section, Financial Market Place (Bloomberg and LSEG terminal) general reading, Quiet reading\n• 3rd Floor: Indian Business Museum\n\n🪑 300+ seats | AC throughout | Power sockets at tables\n💬 Group Discussion Room available — go through the discussion room booking portal. For any queries, ask at the circulation desk for booking\n\n🏢 Floor Plans (links)'}, {'id': 85, 'questions': ['Is there a 24-hour reading hall?', 'Is the library open at night?', 'Study after 9.30 pm, IIMK', 'Night study facility library', 'Is the reading room open all night?', '24/7 study area IIMK'], 'answer': '⏰Night Study / 24×7 Facility:\n\n🌙IIMK Library hours: 24×7 hours\n\n⚠️ The library is open 24 hours.\n\n⏰ Circulation period: 8:00 am to 9:30 pm (all business days)\n\n🏢 For late-night study after 11 PM, check with your hostel warden or academic section about available common rooms or hostel reading rooms.\n\n📅 During exam season, extended hours may be announced — watch notice boards & email.'}, {'id': 86, 'questions': ['Is the library open on holidays?', 'Library hours on public holidays', 'Library on national holidays', 'Library open on Diwali Holi', 'Holiday library timing', 'Is library open during Dussehra?'], 'answer': '🏖️Holiday Hours:\n\n📅 IIMK Library is open 365 days a year!\n\n🏛️Circulation period Statutory/Gazetted Holidays: 9:00 AM – 5:30 PM\n📅Regular Days (excluding weekends): 8:00 AM – 9:30 PM\n\n✅ Even on national holidays like Diwali, Holi, and Independence Day, the library remains open 24×7\n\n📢 Any exceptional closure will be announced on the notice boards/ email, and on the library website.'}, {'id': 87, 'questions': ['Library during exams', 'Extra hours during exam?', 'Exam support library', 'Study during exam time', 'Is the library crowded during exams?', 'Library seat availability during exams'], 'answer': '📝Exam Season Support:\n\n📚 During mid-semester & end-semester exams, the library often:\n• Remains open 24×7\n\n💡Tips for exam season:\n• Arrive early — seats fill up fast!\n• Reserve group discussion room in advance\n• Use OPAC to locate exam-relevant books\n• Renew books online to avoid fines\n\n📢 Check library notice boards or website for special announcements.'}, {'id': 88, 'questions': ['How to enter the library?', 'Library entry process', 'RFID gate library', 'What is the entry check?', 'Library security check', 'Can I enter with a bag?'], 'answer': '🚪Library Entry & Exit:\n\n📋Entry Process:\n1️⃣ Deposit large bags at Bag Deposit Counter (entrance)\n2️⃣ Show IIMK ID at security/gate if asked\n3️⃣ Pass through RFID gate (anti-theft detection)\n\n📋Exit Process:\n• Books must be properly checked out before exit — RFID alarm will trigger if not issued\n• Collect the deposited bag with the token\n\n⚠️ If the RFID alarm triggers accidentally, show your bag & books to security — no issue if properly issued.'}, {'id': 89, 'questions': ['How to give feedback to the library?', 'Library suggestion box', 'Improve library services', 'Complaint to the library', 'Library feedback form', 'How to report an issue with the library?'], 'answer': '💡Feedback & Suggestions:\n\nIIMK Library welcomes your feedback to improve services!\n\n📬Ways to give feedback:\n• 📋Suggestion Box — at the library entrance\n• 📧 Email: library@iimk.ac.in\n• 📞 Phone: 0495-2809 143\n• 🌐 Library website feedback form\n\n💡 For book purchase suggestions, email with title, author, ISBN & reason.\n\n🤝 Connect with Library'}, {'id': 90, 'questions': ['Can alumni use the IIMK library?', 'Library access after graduation', 'Ex-student library access', 'Alumni library membership', 'Library access after leaving IIMK'], 'answer': '🎓Alumni Library Access:\n\n📋 Regular borrowing privileges end upon leaving IIMK.\n\n🏛️Alumni & former researchers may:\n• Visit the Visitor Corner for in-library reading\n• Request limited access for research purposes by contacting the librarian\n• Access open-access resources freely from anywhere\n\n📧 Contact in advance: library@iimk.ac.in\n📞 0495-2809 143\n\n🏛️ Visitor Corner'}, {'id': 91, 'questions': ['Accessibility in the library', 'Disabled student library', 'Wheelchair-accessible library', 'Visually impaired library services', 'Special needs library IIMK', 'Elevator in the library'], 'answer': '♿Accessibility Services:\n\nIIMK Library is committed to inclusive access:\n\n🛗 Elevator available for all floors\n♿ Wheelchair accessible entrance and pathways\n📖 Large-print materials available on request\n💻 Screen reader compatible OPAC\n🤝 Staff assistance available — just ask at the Circulation Desk\n\n📧 Special requirements? Contact in advance: library@iimk.ac.in\n\n♿ Accessibility Info (link)'}, {'id': 92, 'questions': ['Copyright rules in the library', 'Can I copy the entire book?', 'Fair use policy library', 'How much can I photocopy?', 'Copyright for research', 'Can I share journal articles?'], 'answer': "©️Copyright & Fair Use:\n\n📋What's allowed:\n✅ Copy up to 10% of a book or 1 complete chapter\n✅ Download individual articles for personal research\n✅ Share article links (not full PDFs)\n\n❌Not allowed:\n• Copying entire books\n• Bulk/systematic downloading\n• Sharing login credentials\n• Uploading licensed content online\n\n⚠️ Violations can result in an IP block for the entire IIMK campus.\n\n📜 Usage Policy (link)"}, {'id': 93, 'questions': ['How to access Turnitin at IIMK?', 'Turnitin plagiarism check', 'Submit to Turnitin IIMK', 'Turnitin login IIMK', 'Check plagiarism with Turnitin'], 'answer': '🔎Turnitin / iThenticate:\n\n✅Available at IIMK for plagiarism & similarity checking.\n\n📋Access:\nContact computer centre o get a similarity check report\n\n💡 Also check:  Ouriginal (INFLIBNET) — free for IIMK via national license.\n\n🔎 Plagiarism Tools (Quillbot, Grammarly link)'}, {'id': 94, 'questions': ['What is National Digital Library?', 'NDL India IIMK', 'How to register for NDL?', 'NDL free resources', 'National Digital Library India', 'NDLI club IIMK'], 'answer': '📚National Digital Library of India (NDL):\n\n🆓Completely FREE — 90M+ learning resources!\n\n📖Includes: E-books, theses, journal articles, video lectures, and audiobooks across all subjects.\n\n✅How to access:\n1️⃣ Register at ndl.gov.in with IIMK email\n2️⃣ Login and browse freely\n\n🎓NDLI Club at IIMK: Promotes digital literacy & NDL resources.\n\n📚 Open NDL📋 NDLI Registration Guide'}, {'id': 95, 'questions': ['Library help for UG project', 'How to find papers for my project?', 'Research project library resources', 'Literature review help', 'How to start literature survey?', 'Library resources for thesis writing'], 'answer': '🔬Library Help for UG/PG Projects:\n\n📚Step-by-step:\n1️⃣ Define your topic → visit library for subject-specific databases\n2️⃣ Search OPAC for relevant books\n3️⃣ Use databases: Scopus, WoS, ScienceDirect, IEEE\n4️⃣ Use arXiv / NDL for free papers\n5️⃣ Manage references with Zotero / Mendeley\n6️⃣ Check for plagiarism (iThenticate) before submission\n\n🤝 Ask at Reference Desk for personalised guidance!\n\n📋 Subject Guides (link)'}, {'id': 96, 'questions': ['How to submit a thesis to the library?', 'ETD submission IIMK', 'Electronic thesis submission', 'PhD thesis submission library', 'Upload thesis to IDR', 'Thesis format requirements'], 'answer': '📋Thesis / Dissertation Submission (ETD)\n\n📤Step-by-step process\n\n1️⃣ Supervisor & Committee Approval\n2️⃣ Plagiarism Check — Get iThenticate clearance from the Computer Centre\n3️⃣ Format thesis as per IIMK guidelines:\n   • Title Page, Declaration, Certificate, Acknowledgement\n   • Abstract, Table of Contents, List of Figures/Tables\n   • Chapters (Intro → Literature → Methods → Results → Discussion → Conclusion)\n   • References (APA/ACS/APS as per discipline), Appendices\n4️⃣ Submit to Library — Email to libIIMK@IIMK.ac.in:\n   • Thesis soft copy (PDF)\n   • Plagiarism report (iThenticate)\n   • Supervisor approval/viva completion confirmation\n   • Filled ETD submission form\n5️⃣ Library uploads to IDR — DOI assigned, publicly accessible\n\n⚠️ Contact library early — allow processing time!'}]}

# Convenient access to the FAQ entries
entries = knowledge_base["entries"]

# Number of FAQ entries and question variations
total_entries = knowledge_base["total_entries"]

def find_answer(question):
    """Return the answer for an exact matching question variation."""
    question_normalized = question.strip().casefold()

    for entry in entries:
        for q in entry["questions"]:
            if q.strip().casefold() == question_normalized:
                return entry["answer"]

    return None


if __name__ == "__main__":
    print(f"Knowledge base: {knowledge_base['name']}")
    print(f"Total FAQ entries: {total_entries}")
    print(f"Total question variations: {sum(len(e['questions']) for e in entries)}")
